/**
 * First open PR linking to issue `n` (list order), or null.
 */
function findLinkedPr(openPrs, n, ghBranchPattern) {
    for (var i = 0; i < openPrs.length; i++) {
        if (prLinksToIssue(openPrs[i], n, ghBranchPattern)) return openPrs[i];
    }
    return null;
