// Ratchet mode: per-function comparison replaces the max-CRAP threshold for
// known functions; the threshold still applies to functions the baseline
// has never seen. --write-baseline records the current state and passes.
function baselineVerdict(metrics, opts, ctx) {
  const file = path.resolve(ctx.cwd, opts.baseline);
  if (opts.writeBaseline) {
    const doc = buildBaseline(metrics, opts.thresholdValue);
    writeBaseline(file, doc);
    ctx.out.write(`Baseline written: ${opts.baseline} (${Object.keys(doc.functions).length} functions, max ${doc.maxCrap})\n`);
    return 0;
  }
  const baseline = tryStep(ctx, () => readBaseline(file));
  if (baseline === FAIL) return 1;
  if (opts.updateBaseline) return updateVerdict(metrics, baseline, file, opts, ctx);
  const result = compareBaseline(metrics, baseline, opts.thresholdValue);
  ctx.out.write(formatComparison(result, opts.thresholdValue));
  if (result.regressions.length || result.newOverThreshold.length) {
    ctx.err.write('CRAP ratchet failed: CRAP may only decrease.\n');
    return 2;
  }
  return 0;
}

// --update-baseline: ratchet the file down after a merge. A regression (or a new function over the
// threshold) blocks the update and fails, so a red main never silently lowers the bar's evidence.
function updateVerdict(metrics, baseline, file, opts, ctx) {
  const r = ratchetDown(metrics, baseline, opts.thresholdValue);
  ctx.out.write(formatComparison(r.result, opts.thresholdValue));
  if (r.blocked) {
    ctx.err.write('CRAP ratchet failed: baseline NOT updated.\n');
    return 2;
  }
  if (!r.changed) {
    ctx.out.write('Baseline unchanged.\n');
    return 0;
  }
  writeBaseline(file, r.doc);
  ctx.out.write(`Baseline updated: ${Object.keys(r.doc.functions).length} functions (was ${Object.keys(baseline.functions).length}), max ${r.doc.maxCrap} (was ${baseline.maxCrap})\n`);
  return 0;
}

function resolveCoveragePath(opts, cwd) {
  return opts.coverage
    ? path.resolve(cwd, opts.coverage)
    : path.join(cwd, DEFAULT_COVERAGE);
}

function context(streams) {
  return {
    out: streams.out || process.stdout,
    err: streams.err || process.stderr,
    cwd: streams.cwd || process.cwd(),
  };
}

function tryStep(ctx, fn) {
  try {
    return fn();
  } catch (e) {
    ctx.err.write(e.message + '\n');
    return FAIL;
  }
}

function resolveFiles(opts, cwd) {
  if (opts.changed) return changedFiles(cwd);
  if (opts.paths.length > 0) return expandPaths(opts.paths, cwd);
  return findSourceFiles(cwd);
}

function reportVerdict(metrics, threshold, ctx) {
  const max = maxCrap(metrics);
  if (max > threshold) {
    ctx.err.write(
      `CRAP threshold exceeded: ${max.toFixed(1)} > ${threshold.toFixed(1)}\n`,
    );
    return 2;
  }
  return 0;
}

