        new[parts[0] + ':' + parts[1]] = int(parts[2])
grown = [(k, old[k], new[k]) for k in old if k in new and new[k] > old[k]]
removed = [k for k in old if k not in new]
added_over = [(k, v) for k, v in new.items() if k not in old and v > 8]
print("GROWN (regression candidates):", grown)
print("REMOVED from old (functions that changed name):", len(removed))
for k in removed: print("  -", k)
print("NEW over threshold 8:", added_over)
